const anchors = $('Refresh Anchors').all().map(i => i.json);
const backfill = $('Run Backfill').all().map(i => i.json);
const recent = $('Fetch 24h New Labels').all().map(i => i.json);
const promotedNode = $('Promote Suggestions').all().map(i => i.json);
const promotedCount = promotedNode.length ? (promotedNode[0].promote_pattern_suggestions ?? promotedNode[0]) : 0;
const seen = new Set();
const dedupedRecent = recent.filter(r => { const k = r.pattern_name + '|' + (r.labeled_at||''); if (seen.has(k)) return false; seen.add(k); return true; });
const notableAnchors = anchors.filter(r => r && (r.new_anchor_count - r.old_anchor_count) >= 5).map(r => r.pattern_name + ': ' + r.old_anchor_count + ' -> ' + r.new_anchor_count);
const byCat = {};
for (const r of dedupedRecent) { const c = r.pattern_category || 'unknown'; byCat[c] = byCat[c] || []; byCat[c].push(r); }
const catSummary = Object.entries(byCat).sort((a,b) => b[1].length - a[1].length).map(([c, rows]) => c + ': ' + rows.length + ' new labels').join('; ');
const adsProcessed = backfill[0] ? backfill[0].ads_processed : 0;
const suggestionsWritten = backfill[0] ? backfill[0].suggestions_written : 0;
const prompt = ['You are writing a 5-bullet daily ad-pattern digest for ThermoSlim ad intelligence.','','TODAY DATA:','','Anchor changes (patterns whose embedding centroid expanded by >=5 anchors):', notableAnchors.length ? notableAnchors.join('\n') : '(none — all anchors stable today)','','New labels in last 24h, grouped by category:', catSummary || '(none)','','Total new labels: ' + dedupedRecent.length, 'Backfill: ' + adsProcessed + ' ads scanned, ' + suggestionsWritten + ' suggestions written', 'Newly promoted to canonical labels: ' + promotedCount,'','OUTPUT REQUIREMENTS:','- Write EXACTLY 5 bullets, even if data is sparse.','- If little changed, fill bullets with: stable patterns, plateau observations, recommendations to investigate or seed new anchors.','- First bullet: biggest movement OR biggest plateau if nothing moved.','- Bullets 2-3: category-level observations, scoring shifts, brand mix.','- Bullet 4: notable risks (loser-pattern surge, missing data, low promotion volume).','- Bullet 5: ONE concrete action Igor should take this week.','- Each bullet under 25 words. Plain text. Start each with a dash.','- No headers, no markdown, no preamble.'].join('\n');
return { json: { _digestPrompt: prompt, _stats: { notable_anchors: notableAnchors.length, new_labels: dedupedRecent.length, categories_touched: Object.keys(byCat).length, promoted: promotedCount }, _topPatterns: dedupedRecent, _geminiBody: { contents: [{ parts: [{ text: prompt }] }], generationConfig: { temperature: 0.5, maxOutputTokens: 1500 } } } };

const resp = $input.item.json;
const stats = $('Build Digest Prompt').item.json._stats;
const recent = $('Build Digest Prompt').item.json._topPatterns || [];
let text = '(no Gemini text)';
try { text = resp.candidates[0].content.parts[0].text; } catch(e) { text = 'parse error: ' + e.message; }
const today = new Date().toISOString().split('T')[0];
const summary = text + '\n\nStats: ' + stats.new_labels + ' new labels, ' + stats.categories_touched + ' categories, ' + stats.notable_anchors + ' anchor expansions, ' + stats.promoted + ' promoted.';
const patternCounts = {};
const catCounts = {};
for (const r of recent) { patternCounts[r.pattern_name] = (patternCounts[r.pattern_name]||0)+1; catCounts[r.pattern_category] = (catCounts[r.pattern_category]||0)+1; }
const topPatterns = Object.entries(patternCounts).sort((a,b)=>b[1]-a[1]).slice(0,5).map(([k,v]) => k+'('+v+')');
const topCats = Object.entries(catCounts).sort((a,b)=>b[1]-a[1]).slice(0,5).map(([k,v]) => k+'('+v+')');
return { json: { _digestRow: { brand_name: 'ALL', week_start: today, new_ad_count: stats.new_labels, new_hooks: topPatterns, new_angles: topCats, summary_text: summary } } };
